// Independent migrated assertions; compiled and executed only by the parent runner.
using WhimTex.Tests;
using WhimTex.Tests.UnityD;
using System;
using System.Collections;
using System.Reflection;
using UnityEngine;
using DCFApixels.WhimTex;

public static class WhimTexGradientRetiredFieldTests
{
    static TestContext context;
    static MigrationD fixture;

    public static string Run() => TestContext.Run("Archived gradient payloads are explicitly rejected", runContext =>
    {
        context = runContext;
        using (fixture = new MigrationD()) ExecuteMain();
    });

    // Frozen pre-0.12.5 payloads (IDs 0..5). Their version is no longer supported;
    // retain the original bytes and require an explicit version diagnostic.
    static readonly string[] Fixtures = {
        "",
        "",
        "",
        "",
        "",
        ""
    };
    private static void ExecuteMain()
    {
        const BindingFlags flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Static;
        var ser=typeof(WhimTexGradient).Assembly.GetType("DCFApixels.WhimTex.WhimTexDocumentSerializer");
        foreach(string fixture in Fixtures)
        using(var container=new WhimTexDocumentContainer())
        {
            byte[] bytes=Convert.FromBase64String(fixture);
            WhimTexDocumentException rejected = null;
            try
            {
                ser.GetMethod("Deserialize",flags).Invoke(null,
                    new object[] {bytes,container,typeof(WhimTexGradient),null,false});
            }
            catch (TargetInvocationException error) when (error.InnerException is WhimTexDocumentException)
            {
                rejected = (WhimTexDocumentException)error.InnerException;
            }
            context.True(rejected != null && rejected.Message.Contains("Unsupported document payload version: 1"),
                "Archived gradient must fail with its unsupported payload version, not be silently reinterpreted");
        }
        return;
    }
}

